INSERT INTO don_vi_tri_thuc (id, ma, tieu_de, loai, khai_niem_id, truong_phai_id, gia_tri_kich_hoat, dieu_kien_json, noi_dung, cau_hoi, nguon_id, chuong, trang_tu, trang_den, muc_tin_cay, nhan_su_dung, ly_do_nhan, phien_ban, trang_thai, nguoi_tao, nguoi_duyet, ghi_chu) VALUES
(1, 'PYT-PHI-CSCD-2-AI', 'Con số chủ đạo 2 — Đặc điểm & Mục đích sống (Phillips)', 'QUY_TAC', 1, 1, '2', '{"chi_so": "QH_CHU_DAO", "bang": "2"}', 'Theo Phillips, Con số chủ đạo 2 là con số của người kiến tạo hoà bình, giàu lòng trắc ẩn, nhạy cảm tinh tế và có trực giác tốt khi làm việc cùng tập thể.', 'AI', 1, 'Ch.7', 81, 83, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(2, 'PYT-QH-CSCD-2-AI', 'Con số chủ đạo 2 — Góc nhìn thực nghiệm Việt Nam (Quỳnh Hương)', 'QUY_TAC', 1, 1, '2', '{"chi_so": "QH_CHU_DAO", "bang": "2"}', 'Lê Đỗ Quỳnh Hương nhấn mạnh người có Con số chủ đạo 2 tại Việt Nam thường rất giàu tình cảm, giỏi lắng nghe và phát huy tốt nhất khi làm người hỗ trợ đáng tin cậy bên cạnh người dẫn đầu.', 'AI', 2, 'Phần 5', 24, 27, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(3, 'PYT-PHI-CSCD-2-NGHE', 'Con số chủ đạo 2 — Hướng phát triển, khắc phục & Nghề nghiệp', 'QUY_TAC', 1, 1, '2', '{"chi_so": "QH_CHU_DAO", "bang": "2"}', 'Phillips khuyên bạn khắc phục xu hướng thiếu tự tin hoặc phụ thuộc cảm xúc vào người khác, đồng thời phát triển trực giác cân bằng. Nghề nghiệp phù hợp là ngoại giao, tư vấn, hỗ trợ cộng đồng, giáo dục và nghệ thuật.', 'DI_THE_NAO', 1, 'Ch.7', 81, 83, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(4, 'PYT-PHI-CSCD-3-AI', 'Con số chủ đạo 3 — Đặc điểm & Mục đích sống (Phillips)', 'QUY_TAC', 1, 1, '3', '{"chi_so": "QH_CHU_DAO", "bang": "3"}', 'Theo Phillips, Con số chủ đạo 3 gắn liền với trục tư duy nhanh nhạy, khả năng phân tích, óc hài hước và nhu cầu giao tiếp, biểu đạt ý tưởng sống động.', 'AI', 1, 'Ch.7', 84, 87, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(5, 'PYT-QH-CSCD-3-AI', 'Con số chủ đạo 3 — Góc nhìn thực nghiệm Việt Nam (Quỳnh Hương)', 'QUY_TAC', 1, 1, '3', '{"chi_so": "QH_CHU_DAO", "bang": "3"}', 'Theo Quỳnh Hương, người số 3 có đầu óc rất nhạy bén, hoạt ngôn và giàu năng lượng tích cực, nhưng cần chú ý giữ cân bằng cảm xúc trong gia đình.', 'AI', 2, 'Phần 5', 28, 31, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(6, 'PYT-PHI-CSCD-3-NGHE', 'Con số chủ đạo 3 — Hướng phát triển, khắc phục & Nghề nghiệp', 'QUY_TAC', 1, 1, '3', '{"chi_so": "QH_CHU_DAO", "bang": "3"}', 'Phillips khuyên bạn tránh tính hay phê phán hoặc phân tán năng lượng, cần rèn sự kiên nhẫn với người chậm hơn mình. Nghề nghiệp phù hợp gồm truyền thông, giảng dạy, luật pháp, viết lách, nghiên cứu và nghệ thuật biểu diễn.', 'DI_THE_NAO', 1, 'Ch.7', 84, 87, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(7, 'PYT-PHI-CSCD-4-AI', 'Con số chủ đạo 4 — Đặc điểm & Mục đích sống (Phillips)', 'QUY_TAC', 1, 1, '4', '{"chi_so": "QH_CHU_DAO", "bang": "4"}', 'Theo Phillips, Con số chủ đạo 4 thiên về thực hành, nguyên tắc, tỉ mỉ, có năng lực tổ chức và xây dựng nền tảng vật chất vững chắc.', 'AI', 1, 'Ch.7', 88, 91, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(8, 'PYT-QH-CSCD-4-AI', 'Con số chủ đạo 4 — Góc nhìn thực nghiệm Việt Nam (Quỳnh Hương)', 'QUY_TAC', 1, 1, '4', '{"chi_so": "QH_CHU_DAO", "bang": "4"}', 'Theo Quỳnh Hương, người mang Con số chủ đạo 4 rất tháo vát, chuẩn mực và thực tế, là trụ cột đáng tin cậy trong công việc đòi hỏi quy trình chuẩn xác.', 'AI', 2, 'Phần 5', 32, 35, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(9, 'PYT-PHI-CSCD-4-NGHE', 'Con số chủ đạo 4 — Hướng phát triển, khắc phục & Nghề nghiệp', 'QUY_TAC', 1, 1, '4', '{"chi_so": "QH_CHU_DAO", "bang": "4"}', 'Phillips cho rằng bạn cần tránh quá thiên về vật chất hoặc cứng nhắc trong nguyên tắc, hãy mở lòng đón nhận trực giác và sự thư giãn. Nghề nghiệp phù hợp là kỹ thuật, xây dựng, tài chính - ngân hàng, quản trị vận hành và công nghệ.', 'DI_THE_NAO', 1, 'Ch.7', 88, 91, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(10, 'PYT-PHI-CSCD-5-AI', 'Con số chủ đạo 5 — Đặc điểm & Mục đích sống (Phillips)', 'QUY_TAC', 1, 1, '5', '{"chi_so": "QH_CHU_DAO", "bang": "5"}', 'Theo Phillips, Con số chủ đạo 5 nằm ở tâm biểu đồ ngày sinh, đại diện cho khát vọng tự do biểu đạt, giàu cảm xúc, trực giác nhạy bén và thích trải nghiệm mới mẻ.', 'AI', 1, 'Ch.7', 92, 95, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(11, 'PYT-QH-CSCD-5-AI', 'Con số chủ đạo 5 — Góc nhìn thực nghiệm Việt Nam (Quỳnh Hương)', 'QUY_TAC', 1, 1, '5', '{"chi_so": "QH_CHU_DAO", "bang": "5"}', 'Theo Quỳnh Hương, người số 5 rất ghét sự ràng buộc cứng nhắc, giàu lòng trắc ẩn và phát triển mạnh khi tìm được không gian sáng tạo tự do.', 'AI', 2, 'Phần 5', 36, 39, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(12, 'PYT-PHI-CSCD-5-NGHE', 'Con số chủ đạo 5 — Hướng phát triển, khắc phục & Nghề nghiệp', 'QUY_TAC', 1, 1, '5', '{"chi_so": "QH_CHU_DAO", "bang": "5"}', 'Phillips khuyên bạn tránh tâm lý bức bối khi bị gò bó hoặc thay đổi công việc thất thường, cần rèn luyện sự tập trung và kỷ luật tự giác. Nghề nghiệp phù hợp là du lịch, dịch vụ, thương mại, truyền thông, nghệ thuật tự do và đối ngoại.', 'DI_THE_NAO', 1, 'Ch.7', 92, 95, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(13, 'PYT-PHI-CSCD-6-AI', 'Con số chủ đạo 6 — Đặc điểm & Mục đích sống (Phillips)', 'QUY_TAC', 1, 1, '6', '{"chi_so": "QH_CHU_DAO", "bang": "6"}', 'Theo Phillips, Con số chủ đạo 6 kết hợp năng lực sáng tạo thẩm mỹ với tinh thần trách nhiệm sâu sắc đối với gia đình và cộng đồng.', 'AI', 1, 'Ch.7', 96, 99, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(14, 'PYT-QH-CSCD-6-AI', 'Con số chủ đạo 6 — Góc nhìn thực nghiệm Việt Nam (Quỳnh Hương)', 'QUY_TAC', 1, 1, '6', '{"chi_so": "QH_CHU_DAO", "bang": "6"}', 'Theo Quỳnh Hương, người số 6 có trái tim ấm áp, giàu tình yêu thương gia đình nhưng dễ rơi vào cực lo lắng nếu thiếu sự cân bằng nội tâm.', 'AI', 2, 'Phần 5', 40, 43, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(15, 'PYT-PHI-CSCD-6-NGHE', 'Con số chủ đạo 6 — Hướng phát triển, khắc phục & Nghề nghiệp', 'QUY_TAC', 1, 1, '6', '{"chi_so": "QH_CHU_DAO", "bang": "6"}', 'Phillips khuyên bạn khắc phục xu hướng lo âu thái quá hoặc ôm đồm gánh nặng của người khác, hãy giữ thái độ tích cực và tin tưởng. Nghề nghiệp phù hợp là y tế, chăm sóc, giáo dục, thiết kế nội thất, mỹ thuật và công tác xã hội.', 'DI_THE_NAO', 1, 'Ch.7', 96, 99, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(16, 'PYT-PHI-CSCD-7-AI', 'Con số chủ đạo 7 — Đặc điểm & Mục đích sống (Phillips)', 'QUY_TAC', 1, 1, '7', '{"chi_so": "QH_CHU_DAO", "bang": "7"}', 'Theo Phillips, Con số chủ đạo 7 là con số của nhà tư tưởng và người học qua trải nghiệm thực tế sâu sắc, có nhu cầu tự chiêm nghiệm và tìm kiếm chân lý.', 'AI', 1, 'Ch.7', 100, 103, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(17, 'PYT-QH-CSCD-7-AI', 'Con số chủ đạo 7 — Góc nhìn thực nghiệm Việt Nam (Quỳnh Hương)', 'QUY_TAC', 1, 1, '7', '{"chi_so": "QH_CHU_DAO", "bang": "7"}', 'Theo Quỳnh Hương, người có Con số chủ đạo 7 thường trưởng thành mạnh mẽ qua những trải nghiệm tự thân, từ đó tích luỹ chiều sâu triết lý đáng quý.', 'AI', 2, 'Phần 5', 44, 47, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(18, 'PYT-PHI-CSCD-7-NGHE', 'Con số chủ đạo 7 — Hướng phát triển, khắc phục & Nghề nghiệp', 'QUY_TAC', 1, 1, '7', '{"chi_so": "QH_CHU_DAO", "bang": "7"}', 'Phillips cho rằng bạn cần tránh thái độ nổi loạn hoặc khép kín, hãy học cách đón nhận bài học cuộc sống với tâm thế chủ động và chia sẻ tri thức cho cộng đồng. Nghề nghiệp phù hợp là nghiên cứu khoa học, giảng dạy, triết học, công nghệ và phân tích chuyên sâu.', 'DI_THE_NAO', 1, 'Ch.7', 100, 103, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(19, 'PYT-PHI-CSCD-8-AI', 'Con số chủ đạo 8 — Đặc điểm & Mục đích sống (Phillips)', 'QUY_TAC', 1, 1, '8', '{"chi_so": "QH_CHU_DAO", "bang": "8"}', 'Theo Phillips, Con số chủ đạo 8 đại diện cho sự độc lập, trí tuệ điều hành, bản lĩnh quản trị tài chính và lòng nhân ái ẩn dưới vẻ ngoài điềm tĩnh.', 'AI', 1, 'Ch.7', 104, 107, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(20, 'PYT-QH-CSCD-8-AI', 'Con số chủ đạo 8 — Góc nhìn thực nghiệm Việt Nam (Quỳnh Hương)', 'QUY_TAC', 1, 1, '8', '{"chi_so": "QH_CHU_DAO", "bang": "8"}', 'Theo Quỳnh Hương, người số 8 rất có duyên với hoạt động kinh doanh và quản lý khi đã rèn được trí tuệ cảm xúc và sự tự chủ.', 'AI', 2, 'Phần 5', 48, 51, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(21, 'PYT-PHI-CSCD-8-NGHE', 'Con số chủ đạo 8 — Hướng phát triển, khắc phục & Nghề nghiệp', 'QUY_TAC', 1, 1, '8', '{"chi_so": "QH_CHU_DAO", "bang": "8"}', 'Phillips khuyên bạn học cách bày tỏ cảm xúc và lòng biết ơn với người thân (vì người số 8 thường khó nói lời mềm mỏng), đồng thời giữ sự minh bạch về đạo đức kinh doanh. Nghề nghiệp phù hợp là tài chính - ngân hàng, quản trị doanh nghiệp, thương mại lớn và luật.', 'DI_THE_NAO', 1, 'Ch.7', 104, 107, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(22, 'PYT-PHI-CSCD-9-AI', 'Con số chủ đạo 9 — Đặc điểm & Mục đích sống (Phillips)', 'QUY_TAC', 1, 1, '9', '{"chi_so": "QH_CHU_DAO", "bang": "9"}', 'Theo Phillips, Con số chủ đạo 9 hội tụ hoài bão lớn, tinh thần trách nhiệm và lý tưởng nhân đạo, luôn đặt giá trị con người lên hàng đầu.', 'AI', 1, 'Ch.7', 108, 110, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(23, 'PYT-QH-CSCD-9-AI', 'Con số chủ đạo 9 — Góc nhìn thực nghiệm Việt Nam (Quỳnh Hương)', 'QUY_TAC', 1, 1, '9', '{"chi_so": "QH_CHU_DAO", "bang": "9"}', 'Theo Quỳnh Hương, người có Con số chủ đạo 9 rất giàu lòng nhân ái, sống vì cộng đồng nhưng cần rèn sự tỉnh táo và kiên nhẫn trong thực tế.', 'AI', 2, 'Phần 5', 52, 55, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(24, 'PYT-PHI-CSCD-9-NGHE', 'Con số chủ đạo 9 — Hướng phát triển, khắc phục & Nghề nghiệp', 'QUY_TAC', 1, 1, '9', '{"chi_so": "QH_CHU_DAO", "bang": "9"}', 'Phillips khuyên bạn học cách quản lý tài chính thực tế (tránh cả tin hoặc chi tiêu cảm tính) và chuyển hoá lý tưởng thành hành động khả thi. Nghề nghiệp phù hợp là công tác xã hội, giáo dục, y tế, văn hoá nghệ thuật và hoạt động cộng đồng.', 'DI_THE_NAO', 1, 'Ch.7', 108, 110, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(25, 'PYT-PHI-CSCD-10-AI', 'Con số chủ đạo 10 — Đặc điểm & Mục đích sống (Phillips)', 'QUY_TAC', 1, 1, '10', '{"chi_so": "QH_CHU_DAO", "bang": "10"}', 'Theo Phillips, Con số chủ đạo 10 mang khả năng thích nghi vượt trội, tính cách quảng giao, tự tin, năng động và có tiềm năng bứt phá khi sống tích cực.', 'AI', 1, 'Ch.7', 111, 113, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(26, 'PYT-QH-CSCD-10-AI', 'Con số chủ đạo 10 — Góc nhìn thực nghiệm Việt Nam (Quỳnh Hương)', 'QUY_TAC', 1, 1, '10', '{"chi_so": "QH_CHU_DAO", "bang": "10"}', 'Theo Quỳnh Hương, trong hệ Pythagoras của Phillips/QH, số 10 được giữ riêng (không rút về 1 như Decoz hay Johari) vì kết hợp bản lĩnh độc lập của số 1 với tiềm năng linh hoạt của số 0.', 'AI', 2, 'Phần 5', 56, 58, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(27, 'PYT-PHI-CSCD-10-NGHE', 'Con số chủ đạo 10 — Hướng phát triển, khắc phục & Nghề nghiệp', 'QUY_TAC', 1, 1, '10', '{"chi_so": "QH_CHU_DAO", "bang": "10"}', 'Phillips lưu ý bạn tránh sự hời hợt, tự mãn hoặc nóng nảy khi gặp trở ngại, cần phát huy kỷ luật bản thân để không lãng phí tài năng. Nghề nghiệp phù hợp là kinh doanh, bán hàng, thể thao, thiết kế, du lịch và quản lý dự án.', 'DI_THE_NAO', 1, 'Ch.7', 111, 113, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(28, 'PYT-PHI-CSCD-11-AI', 'Con số chủ đạo 11 — Đặc điểm & Mục đích sống (Phillips)', 'QUY_TAC', 1, 1, '11', '{"chi_so": "QH_CHU_DAO", "bang": "11"}', 'Theo Phillips, Con số chủ đạo 11 là con số có trường năng lượng tâm linh và trực giác rất cao, giàu lòng trắc ẩn và nhạy cảm với cái đẹp tinh thần.', 'AI', 1, 'Ch.7', 114, 115, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(29, 'PYT-QH-CSCD-11-AI', 'Con số chủ đạo 11 — Góc nhìn thực nghiệm Việt Nam (Quỳnh Hương)', 'QUY_TAC', 1, 1, '11', '{"chi_so": "QH_CHU_DAO", "bang": "11"}', 'Theo Quỳnh Hương, người mang Con số chủ đạo 11 có trực giác nhạy bén nhưng nếu chưa sẵn sàng đón nhận áp lực của số bậc thầy thì thường biểu hiện gần với số 2.', 'AI', 2, 'Phần 5', 59, 60, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(30, 'PYT-PHI-CSCD-11-NGHE', 'Con số chủ đạo 11 — Hướng phát triển, khắc phục & Nghề nghiệp', 'QUY_TAC', 1, 1, '11', '{"chi_so": "QH_CHU_DAO", "bang": "11"}', 'Phillips khuyên bạn giữ lối sống cân bằng, tránh bị cuốn vào cám dỗ vật chất quá mức và phát triển năng lực dẫn dắt tinh thần. Nghề nghiệp phù hợp là giáo dục, tư vấn tâm lý, nghệ thuật, văn hoá và hoạt động nhân văn.', 'DI_THE_NAO', 1, 'Ch.7', 114, 115, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(31, 'PYT-PHI-CSCD-22_4-AI', 'Con số chủ đạo 22/4 — Đặc điểm & Mục đích sống (Phillips)', 'QUY_TAC', 1, 1, '22/4', '{"chi_so": "QH_CHU_DAO", "bang": "22/4"}', 'Theo Phillips, Con số chủ đạo 22/4 (Con số Vua / Master Architect) kết hợp trực giác tầm nhìn của số 11 với tính thực tiễn kỷ luật của số 4, có tiềm năng hiện thực hoá các công trình lớn vì cộng đồng.', 'AI', 1, 'Ch.7', 116, 117, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
