(75, 'PYT-PHI-BD-8-X2', 'Biểu đồ ngày sinh: Số 8 xuất hiện 2 lần', 'QUY_TAC', 3, 1, '8:2', '{"chi_so": "BIEU_DO_DEM", "so": 8, "bang": 2}', 'Hai số 8 (88) trong biểu đồ: Theo Phillips, khả năng quan sát chi tiết và đánh giá tình huống rất sắc bén, thích đi du lịch và khám phá.', 'AI', 1, 'Ch.5', 39, 42, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(76, 'PYT-PHI-BD-8-X3', 'Biểu đồ ngày sinh: Số 8 xuất hiện 3 lần', 'QUY_TAC', 3, 1, '8:3', '{"chi_so": "BIEU_DO_DEM", "so": 8, "bang": 3}', 'Ba số 8 (888) trong biểu đồ: Theo Phillips, khi sống tích cực bạn đạt tới trí tuệ quản trị và sự độc lập tài chính cao; nếu tiêu cực dễ trở nên bồn chồn.', 'AI', 1, 'Ch.5', 39, 42, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
