(148, 'PYT-QH-TEN-RIENG-22_4', 'Con số tên riêng 22/4 (Quỳnh Hương — Linh hồn + Biểu đạt)', 'QUY_TAC', 8, 1, '22/4', '{"chi_so": "QH_TEN_RIENG", "bang": "22/4"}', 'Theo Lê Đỗ Quỳnh Hương (Phần 12), Con số tên riêng 22/4 tổng hợp cả nội tâm (nguyên âm) và biểu đạt (phụ âm), đóng vai trò nguồn năng lượng bổ trợ cho Con số chủ đạo của bạn theo hướng số 22/4.', 'AI', 2, 'Phần 12', 350, 351, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(149, 'PYT-PHI-PYN-1-GAP', 'Năm cá nhân 1 — Năm khởi đầu mới & điều chỉnh chủ động', 'QUY_TAC', 10, 1, '1', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 1}', 'Theo Phillips và Quỳnh Hương, Năm cá nhân 1 là đỉnh đầu của chu kỳ 9 năm mới: thời điểm mạnh mẽ để tự khẳng định, thay đổi thói quen cũ và gieo hạt giống cho các dự án dài hạn. (Lưu ý: theo Phillips, có khúc giao thời từ 2–5 tháng cuối năm trước chuyển sang năm mới).', 'GAP_GI', 1, 'Ch.9', 135, 138, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(150, 'PYT-PHI-PYN-1-DI', 'Việc nên và không nên làm trong Năm cá nhân 1', 'QUY_TAC', 10, 1, '1', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 1}', 'Trong Năm cá nhân 1, Phillips khuyên bạn chủ động nắm bắt cơ hội mới, rèn tính kỷ luật tự giác và không nên tiêu xài bốc đồng hay hành động ích kỷ.', 'DI_THE_NAO', 1, 'Ch.9', 135, 138, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(151, 'PYT-PHI-PYN-2-GAP', 'Năm cá nhân 2 — Năm phát triển tâm linh & hợp tác chia sẻ', 'QUY_TAC', 10, 1, '2', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 2}', 'Theo Phillips, Năm cá nhân 2 chuyển nhịp từ hành động dồn dập sang lắng dịu nội tâm, phát triển trực giác, kiểm soát cảm xúc và tăng cường sự hợp tác. (Lưu ý: theo Phillips, có khúc giao thời từ 2–5 tháng cuối năm trước chuyển sang năm mới).', 'GAP_GI', 1, 'Ch.9', 139, 142, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(152, 'PYT-PHI-PYN-2-DI', 'Việc nên và không nên làm trong Năm cá nhân 2', 'QUY_TAC', 10, 1, '2', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 2}', 'Trong Năm cá nhân 2, bạn nên dành thời gian thiền định, lắng nghe và vun đắp quan hệ đối tác; tránh nóng vội, tranh cãi hoặc tự mãn.', 'DI_THE_NAO', 1, 'Ch.9', 139, 142, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(153, 'PYT-PHI-PYN-3-GAP', 'Năm cá nhân 3 — Năm mở rộng tư duy & học hỏi', 'QUY_TAC', 10, 1, '3', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 3}', 'Theo Phillips, Năm cá nhân 3 kích hoạt mạnh mẽ trục trí não, thúc đẩy nhu cầu học tập, nghiên cứu, du lịch mở mang tầm mắt và giao lưu xã hội. (Lưu ý: theo Phillips, có khúc giao thời từ 2–5 tháng cuối năm trước chuyển sang năm mới).', 'GAP_GI', 1, 'Ch.9', 143, 146, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(154, 'PYT-PHI-PYN-3-DI', 'Việc nên và không nên làm trong Năm cá nhân 3', 'QUY_TAC', 10, 1, '3', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 3}', 'Trong Năm cá nhân 3, bạn nên tham gia các khoá học mới, rèn luyện trí nhớ và giữ tinh thần vui vẻ; tránh chỉ trích người khác hoặc ôm đồm quá nhiều kế hoạch trên giấy.', 'DI_THE_NAO', 1, 'Ch.9', 143, 146, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(155, 'PYT-PHI-PYN-4-GAP', 'Năm cá nhân 4 — Năm trũng củng cố nền tảng & nghỉ ngơi', 'QUY_TAC', 10, 1, '4', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 4}', 'Theo Phillips và Quỳnh Hương, Năm cá nhân 4 là ''năm trũng'' đầu tiên trong chu kỳ 9 năm: giai đoạn cần củng cố nội lực, sắp xếp lại công việc và tỉa bỏ những phần không còn hiệu quả. (Lưu ý: theo Phillips, có khúc giao thời từ 2–5 tháng cuối năm trước chuyển sang năm mới).', 'GAP_GI', 1, 'Ch.9', 147, 150, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(156, 'PYT-PHI-PYN-4-DI', 'Việc nên và không nên làm trong Năm cá nhân 4', 'QUY_TAC', 10, 1, '4', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 4}', 'Trong Năm cá nhân 4, Phillips đặc biệt khuyên bạn KHÔNG nên mạo hiểm đầu tư lớn, nhảy việc hay thay đổi đột ngột; hãy ưu tiên nghỉ ngơi, giữ gìn sức khoẻ và hoàn thiện nền tảng sẵn có.', 'DI_THE_NAO', 1, 'Ch.9', 147, 150, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(157, 'PYT-PHI-PYN-5-GAP', 'Năm cá nhân 5 — Năm của tự do, sáng tạo & chuyển dịch', 'QUY_TAC', 10, 1, '5', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 5}', 'Theo Phillips, Năm cá nhân 5 giải phóng năng lượng sau năm củng cố số 4, mang lại khát vọng tự do biểu đạt, kết nối xã hội và những bước chuyển mới mẻ. (Lưu ý: theo Phillips, có khúc giao thời từ 2–5 tháng cuối năm trước chuyển sang năm mới).', 'GAP_GI', 1, 'Ch.9', 151, 154, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(158, 'PYT-PHI-PYN-5-DI', 'Việc nên và không nên làm trong Năm cá nhân 5', 'QUY_TAC', 10, 1, '5', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 5}', 'Trong Năm cá nhân 5, bạn nên phát triển kỹ năng nghệ thuật, mở rộng giao tiếp hoặc dịch chuyển hợp lý; tránh buông thả hoặc nhầm lẫn tự do với sự thiếu trách nhiệm.', 'DI_THE_NAO', 1, 'Ch.9', 151, 154, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(159, 'PYT-PHI-PYN-6-GAP', 'Năm cá nhân 6 — Đỉnh nhỏ của sáng tạo & trách nhiệm gia đình', 'QUY_TAC', 10, 1, '6', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 6}', 'Theo Phillips, Năm cá nhân 6 là một đỉnh nhỏ thuận lợi cho các dự án sáng tạo, nghệ thuật và củng cố sự gắn kết, trách nhiệm trong mái ấm gia đình. (Lưu ý: theo Phillips, có khúc giao thời từ 2–5 tháng cuối năm trước chuyển sang năm mới).', 'GAP_GI', 1, 'Ch.9', 155, 158, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(160, 'PYT-PHI-PYN-6-DI', 'Việc nên và không nên làm trong Năm cá nhân 6', 'QUY_TAC', 10, 1, '6', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 6}', 'Trong Năm cá nhân 6, bạn nên đầu tư thời gian cho tổ ấm và các dự án nhân văn; tránh lo âu thái quá hoặc để mâu thuẫn tình cảm kéo dài.', 'DI_THE_NAO', 1, 'Ch.9', 155, 158, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(161, 'PYT-PHI-PYN-7-GAP', 'Năm cá nhân 7 — Năm trũng của sự tập trung, trải nghiệm & đúc kết', 'QUY_TAC', 10, 1, '7', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 7}', 'Theo Phillips và Quỳnh Hương, Năm cá nhân 7 là năm trũng thứ hai trong chu kỳ 9 năm: thời điểm hướng nội để chiêm nghiệm, học qua trải nghiệm thực tế và chia sẻ tri thức. (Lưu ý: theo Phillips, có khúc giao thời từ 2–5 tháng cuối năm trước chuyển sang năm mới).', 'GAP_GI', 1, 'Ch.9', 159, 162, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(162, 'PYT-PHI-PYN-7-DI', 'Việc nên và không nên làm trong Năm cá nhân 7', 'QUY_TAC', 10, 1, '7', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 7}', 'Trong Năm cá nhân 7, Phillips khuyên bạn tránh mở rộng kinh doanh mạo hiểm hay thay đổi lớn về tài chính; hãy tập trung nâng cao chuyên môn, giảng dạy và rèn sự điềm tĩnh trước thử thách.', 'DI_THE_NAO', 1, 'Ch.9', 159, 162, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(163, 'PYT-PHI-PYN-8-GAP', 'Năm cá nhân 8 — Năm phát triển độc lập, trí tuệ & tài chính', 'QUY_TAC', 10, 1, '8', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 8}', 'Theo Phillips, Năm cá nhân 8 đánh dấu sự bứt phá mạnh mẽ khỏi đáy trũng số 7 để vươn lên đỉnh cao độc lập, trí tuệ điều hành và cải thiện tài chính. (Lưu ý: theo Phillips, có khúc giao thời từ 2–5 tháng cuối năm trước chuyển sang năm mới).', 'GAP_GI', 1, 'Ch.9', 163, 166, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(164, 'PYT-PHI-PYN-8-DI', 'Việc nên và không nên làm trong Năm cá nhân 8', 'QUY_TAC', 10, 1, '8', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 8}', 'Trong Năm cá nhân 8, bạn nên chủ động nắm bắt cơ hội thương mại với sự minh bạch đạo đức cao nhất; tránh xa cách người thân vì quá mải mê công việc.', 'DI_THE_NAO', 1, 'Ch.9', 163, 166, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(165, 'PYT-PHI-PYN-9-GAP', 'Năm cá nhân 9 — Đỉnh cao thay đổi, hoàn tất chu kỳ & trách nhiệm cộng đồng', 'QUY_TAC', 10, 1, '9', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 9}', 'Theo Phillips và Quỳnh Hương, Năm cá nhân 9 là đỉnh cao nhất khép lại chu kỳ 9 năm cũ và mở đường cho chu kỳ mới: thường có những bước ngoặt lớn về công việc, nơi ở, chuyến đi xa hoặc khép lại các mối quan hệ đã hết duyên. (Lưu ý: theo Phillips, có khúc giao thời từ 2–5 tháng cuối năm trước chuyển sang năm mới).', 'GAP_GI', 1, 'Ch.9', 131, 134, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(166, 'PYT-PHI-PYN-9-DI', 'Việc nên và không nên làm trong Năm cá nhân 9', 'QUY_TAC', 10, 1, '9', '{"chi_so": "QH_NAM_CA_NHAN", "bang": 9}', 'Trong Năm cá nhân 9, bạn nên chủ động hoàn tất các cam kết cũ, hành xử bao dung vì lợi ích chung và tránh sự liều lĩnh hay tham vọng vị kỷ.', 'DI_THE_NAO', 1, 'Ch.9', 131, 134, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(167, 'PYT-PHI-THANG-1', 'Tháng cá nhân 1 (Phillips Ch.9 / Decoz Ch.6)', 'QUY_TAC', 11, 1, '1', '{"chi_so": "QH_THANG_CA_NHAN", "bang": 1}', 'Theo biến thể tháng trong Chu kỳ 9 năm của Phillips (Ch.9, tr.PDF 107–129) và công thức Tháng cá nhân của Decoz (Ch.6, tr.188), Tháng cá nhân 1 là tháng của sự chủ động, tự khẳng định và đưa các ý tưởng mới vào hành động thực tế.', 'GAP_GI', 1, 'Ch.9', 107, 129, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF (sách in tr.127-168; công thức Decoz tr.188)'),
(168, 'PYT-PHI-THANG-2', 'Tháng cá nhân 2 (Phillips Ch.9 / Decoz Ch.6)', 'QUY_TAC', 11, 1, '2', '{"chi_so": "QH_THANG_CA_NHAN", "bang": 2}', 'Theo Phillips (Ch.9, tr.PDF 108–127) và Decoz (tr.189), Tháng cá nhân 2 nhấn mạnh sự lắng nghe trực giác, giữ bình tĩnh cảm xúc, hợp tác hài hoà và dành thời gian thư giãn tái tạo năng lượng.', 'GAP_GI', 1, 'Ch.9', 107, 129, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF (sách in tr.127-168; công thức Decoz tr.188)'),
(169, 'PYT-PHI-THANG-3', 'Tháng cá nhân 3 (Phillips Ch.9 / Decoz Ch.6)', 'QUY_TAC', 11, 1, '3', '{"chi_so": "QH_THANG_CA_NHAN", "bang": 3}', 'Theo Phillips (Ch.9, tr.PDF 108–127) và Decoz (tr.190), Tháng cá nhân 3 kích thích mạnh mẽ tư duy, trí nhớ và sự sáng tạo; rất phù hợp để học tập, lập kế hoạch hoặc trao đổi ý tưởng.', 'GAP_GI', 1, 'Ch.9', 107, 129, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF (sách in tr.127-168; công thức Decoz tr.188)'),
(170, 'PYT-PHI-THANG-4', 'Tháng cá nhân 4 (Phillips Ch.9 / Decoz Ch.6)', 'QUY_TAC', 11, 1, '4', '{"chi_so": "QH_THANG_CA_NHAN", "bang": 4}', 'Theo Phillips (Ch.9, tr.PDF 110–127) và Decoz (tr.190), Tháng cá nhân 4 là tháng rà soát, củng cố nền tảng, sắp xếp công việc ngăn nắp và giữ sự điều độ, tránh làm việc quá sức.', 'GAP_GI', 1, 'Ch.9', 107, 129, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF (sách in tr.127-168; công thức Decoz tr.188)'),
(171, 'PYT-PHI-THANG-5', 'Tháng cá nhân 5 (Phillips Ch.9 / Decoz Ch.6)', 'QUY_TAC', 11, 1, '5', '{"chi_so": "QH_THANG_CA_NHAN", "bang": 5}', 'Theo Phillips (Ch.9, tr.PDF 110–127) và Decoz (tr.190), Tháng cá nhân 5 mang lại cảm hứng tự do biểu đạt, sự linh hoạt và niềm vui kết nối với người thân, bạn bè.', 'GAP_GI', 1, 'Ch.9', 107, 129, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF (sách in tr.127-168; công thức Decoz tr.188)'),
(172, 'PYT-PHI-THANG-6', 'Tháng cá nhân 6 (Phillips Ch.9 / Decoz Ch.6)', 'QUY_TAC', 11, 1, '6', '{"chi_so": "QH_THANG_CA_NHAN", "bang": 6}', 'Theo Phillips (Ch.9, tr.PDF 110–128) và Decoz (tr.191), Tháng cá nhân 6 hướng trọng tâm vào sáng tạo, chăm sóc mái ấm gia đình và hoàn thiện các trách nhiệm chung với tâm thế tích cực.', 'GAP_GI', 1, 'Ch.9', 107, 129, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF (sách in tr.127-168; công thức Decoz tr.188)'),
(173, 'PYT-PHI-THANG-7', 'Tháng cá nhân 7 (Phillips Ch.9 / Decoz Ch.6)', 'QUY_TAC', 11, 1, '7', '{"chi_so": "QH_THANG_CA_NHAN", "bang": 7}', 'Theo Phillips (Ch.9, tr.PDF 111–128) và Decoz (tr.191), Tháng cá nhân 7 là tháng đi vào chiều sâu thực hành và chiêm nghiệm triết lý, buông bỏ những chi tiết rườm rà không còn phù hợp.', 'GAP_GI', 1, 'Ch.9', 107, 129, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF (sách in tr.127-168; công thức Decoz tr.188)'),
(174, 'PYT-PHI-THANG-8', 'Tháng cá nhân 8 (Phillips Ch.9 / Decoz Ch.6)', 'QUY_TAC', 11, 1, '8', '{"chi_so": "QH_THANG_CA_NHAN", "bang": 8}', 'Theo Phillips (Ch.9, tr.PDF 111–128) và Decoz (tr.191), Tháng cá nhân 8 thuận lợi cho tính tự chủ, ra quyết định sáng suốt về tài chính - công việc dựa trên sự minh bạch.', 'GAP_GI', 1, 'Ch.9', 107, 129, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF (sách in tr.127-168; công thức Decoz tr.188)'),
(175, 'PYT-PHI-THANG-9', 'Tháng cá nhân 9 (Phillips Ch.9 / Decoz Ch.6)', 'QUY_TAC', 11, 1, '9', '{"chi_so": "QH_THANG_CA_NHAN", "bang": 9}', 'Theo Phillips (Ch.9, tr.PDF 109–128) và Decoz (tr.191), Tháng cá nhân 9 là tháng tổng kết, hoàn tất các phần việc dở dang và chuẩn bị tâm thế sẵn sàng cho bước chuyển tiếp theo.', 'GAP_GI', 1, 'Ch.9', 107, 129, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', 'trang PDF (sách in tr.127-168; công thức Decoz tr.188)'),
(176, 'PYT-PHI-DINH-1-GAP', 'Đỉnh Kim tự tháp số 1 — Giai đoạn nỗ lực cá nhân & tự lập', 'QUY_TAC', 12, 1, '1', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "1"}', 'Theo Phillips và Quỳnh Hương, khi bước vào Đỉnh số 1, cuộc sống thúc đẩy bạn tách khỏi những khuôn mẫu phụ thuộc để tự đứng trên đôi chân của mình và phát triển bản sắc cá nhân.', 'GAP_GI', 1, 'Ch.11', 175, 176, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(177, 'PYT-PHI-DINH-1-DI', 'Hướng đi trong Đỉnh Kim tự tháp số 1 — Giai đoạn nỗ lực cá nhân & tự lập', 'QUY_TAC', 12, 1, '1', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "1"}', 'Ở Đỉnh số 1, bạn nên rèn luyện bản lĩnh tự chủ, kiên trì phát triển chuyên môn riêng và giữ sự điềm tĩnh khi cần đưa ra lựa chọn độc lập.', 'DI_THE_NAO', 1, 'Ch.11', 175, 176, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(178, 'PYT-PHI-DINH-2-GAP', 'Đỉnh Kim tự tháp số 2 — Giai đoạn phát triển trực giác & lối sống tình cảm', 'QUY_TAC', 12, 1, '2', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "2"}', 'Theo Phillips, Đỉnh số 2 là giai đoạn các giá trị tinh thần, sự thấu cảm và trực giác phát triển chậm mà chắc; đòi hỏi sự kiên nhẫn và hài hoà trong hợp tác.', 'GAP_GI', 1, 'Ch.11', 176, 177, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(179, 'PYT-PHI-DINH-2-DI', 'Hướng đi trong Đỉnh Kim tự tháp số 2 — Giai đoạn phát triển trực giác & lối sống tình cảm', 'QUY_TAC', 12, 1, '2', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "2"}', 'Ở Đỉnh số 2, bạn cần kiểm soát cảm xúc, tránh chạy theo tham vọng vật chất vội vàng mà đánh mất sự bình yên nội tâm.', 'DI_THE_NAO', 1, 'Ch.11', 176, 177, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(180, 'PYT-PHI-DINH-3-GAP', 'Đỉnh Kim tự tháp số 3 — Giai đoạn mở mang trí tuệ & học hỏi', 'QUY_TAC', 12, 1, '3', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "3"}', 'Theo Phillips, Đỉnh số 3 mở ra thời kỳ học tập, nghiên cứu, đi xa khám phá và phát triển năng lực tư duy phân tích.', 'GAP_GI', 1, 'Ch.11', 177, 178, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(181, 'PYT-PHI-DINH-3-DI', 'Hướng đi trong Đỉnh Kim tự tháp số 3 — Giai đoạn mở mang trí tuệ & học hỏi', 'QUY_TAC', 12, 1, '3', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "3"}', 'Ở Đỉnh số 3, bạn nên đầu tư nâng cao trình độ học vấn hoặc chuyên môn, đồng thời tránh tâm lý hay phán xét, chỉ trích.', 'DI_THE_NAO', 1, 'Ch.11', 177, 178, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(182, 'PYT-PHI-DINH-4-GAP', 'Đỉnh Kim tự tháp số 4 — Giai đoạn lao động thực tế & xây dựng nền móng', 'QUY_TAC', 12, 1, '4', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "4"}', 'Theo Phillips, Đỉnh số 4 mang lại năng lượng làm việc thực tiễn, kỷ luật và khả năng củng cố nền tảng vật chất, nghề nghiệp vững vàng.', 'GAP_GI', 1, 'Ch.11', 178, 179, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(183, 'PYT-PHI-DINH-4-DI', 'Hướng đi trong Đỉnh Kim tự tháp số 4 — Giai đoạn lao động thực tế & xây dựng nền móng', 'QUY_TAC', 12, 1, '4', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "4"}', 'Ở Đỉnh số 4, bạn nên làm việc có kế hoạch, kiên trì tích luỹ và tránh thái độ tham lam hay làm việc quá sức gây căng thẳng.', 'DI_THE_NAO', 1, 'Ch.11', 178, 179, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(184, 'PYT-PHI-DINH-5-GAP', 'Đỉnh Kim tự tháp số 5 — Giai đoạn giải phóng tự do & trưởng thành tâm thức', 'QUY_TAC', 12, 1, '5', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "5"}', 'Theo Phillips, Đỉnh số 5 gắn liền với việc vượt qua các rào cản tâm lý để đạt tới sự tự do nội tâm và khả năng thấu hiểu cảm xúc sâu sắc.', 'GAP_GI', 1, 'Ch.11', 179, 180, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(185, 'PYT-PHI-DINH-5-DI', 'Hướng đi trong Đỉnh Kim tự tháp số 5 — Giai đoạn giải phóng tự do & trưởng thành tâm thức', 'QUY_TAC', 12, 1, '5', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "5"}', 'Ở Đỉnh số 5, bạn nên lắng nghe trực giác để chọn hướng đi sáng tạo, tự chủ, tránh lo âu về an toàn vật chất mà đánh mất cơ hội đổi mới.', 'DI_THE_NAO', 1, 'Ch.11', 179, 180, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(186, 'PYT-PHI-DINH-6-GAP', 'Đỉnh Kim tự tháp số 6 — Giai đoạn phát triển sáng tạo & vun đắp tổ ấm', 'QUY_TAC', 12, 1, '6', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "6"}', 'Theo Phillips, Đỉnh số 6 kết nối năng lượng trí não với sự sáng tạo cao độ, thường mang lại thành tựu trong nghệ thuật, công việc sáng tạo hoặc trách nhiệm lớn với gia đình.', 'GAP_GI', 1, 'Ch.11', 180, 181, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(187, 'PYT-PHI-DINH-6-DI', 'Hướng đi trong Đỉnh Kim tự tháp số 6 — Giai đoạn phát triển sáng tạo & vun đắp tổ ấm', 'QUY_TAC', 12, 1, '6', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "6"}', 'Ở Đỉnh số 6, bạn cần giữ cái nhìn lạc quan, cân bằng giữa cống hiến cho gia đình với việc phát triển tài năng sáng tạo cá nhân.', 'DI_THE_NAO', 1, 'Ch.11', 180, 181, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(188, 'PYT-PHI-DINH-7-GAP', 'Đỉnh Kim tự tháp số 7 — Giai đoạn đúc kết trải nghiệm & chia sẻ tri thức', 'QUY_TAC', 12, 1, '7', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "7"}', 'Theo Phillips, Đỉnh số 7 là giai đoạn có nhiều thử thách thực tế giúp bạn tôi luyện bản lĩnh, đạt tới sự thấu suốt triết lý và trở thành người truyền đạt kinh nghiệm.', 'GAP_GI', 1, 'Ch.11', 181, 182, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(189, 'PYT-PHI-DINH-7-DI', 'Hướng đi trong Đỉnh Kim tự tháp số 7 — Giai đoạn đúc kết trải nghiệm & chia sẻ tri thức', 'QUY_TAC', 12, 1, '7', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "7"}', 'Ở Đỉnh số 7, bạn nên đón nhận mọi trải nghiệm với tâm thế học hỏi và tích cực chia sẻ kiến thức đã tích luỹ cho cộng đồng (giảng dạy, cố vấn).', 'DI_THE_NAO', 1, 'Ch.11', 181, 182, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(190, 'PYT-PHI-DINH-8-GAP', 'Đỉnh Kim tự tháp số 8 — Giai đoạn phát huy trí tuệ độc lập & điều hành', 'QUY_TAC', 12, 1, '8', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "8"}', 'Theo Phillips, Đỉnh số 8 mở ra cơ hội thành công thông qua sự độc lập, năng lực tổ chức thương mại hoặc sáng tạo độc đáo tuỳ theo Con số chủ đạo là chẵn hay lẻ.', 'GAP_GI', 1, 'Ch.11', 182, 183, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(191, 'PYT-PHI-DINH-8-DI', 'Hướng đi trong Đỉnh Kim tự tháp số 8 — Giai đoạn phát huy trí tuệ độc lập & điều hành', 'QUY_TAC', 12, 1, '8', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "8"}', 'Ở Đỉnh số 8, bạn cần phát huy tính tự chủ và trí tuệ minh mẫn, tránh để cái tôi cá nhân hoặc sự lạnh lùng tạo khoảng cách với mọi người.', 'DI_THE_NAO', 1, 'Ch.11', 182, 183, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(192, 'PYT-PHI-DINH-9-GAP', 'Đỉnh Kim tự tháp số 9 — Giai đoạn phụng sự nhân văn & chuyển hoá lớn', 'QUY_TAC', 12, 1, '9', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "9"}', 'Theo Phillips, Đỉnh số 9 kêu gọi bạn đặt năng lượng vào các hoạt động nhân đạo, giáo dục, văn hoá hoặc những dự án mang lại giá trị cho cộng đồng.', 'GAP_GI', 1, 'Ch.11', 183, 184, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(193, 'PYT-PHI-DINH-9-DI', 'Hướng đi trong Đỉnh Kim tự tháp số 9 — Giai đoạn phụng sự nhân văn & chuyển hoá lớn', 'QUY_TAC', 12, 1, '9', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "9"}', 'Ở Đỉnh số 9, bạn nên hành động với tinh thần trách nhiệm cao và lòng bao dung, sẵn sàng buông bỏ những khuôn mẫu cũ kỹ.', 'DI_THE_NAO', 1, 'Ch.11', 183, 184, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(194, 'PYT-PHI-DINH-10-GAP', 'Đỉnh Kim tự tháp số 10 — Giai đoạn dẫn dắt & nâng đỡ tinh thần (Đỉnh 3–4)', 'QUY_TAC', 12, 1, '10', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "10"}', 'Theo Phillips và Quỳnh Hương, số 10 chỉ xuất hiện ở Đỉnh 3 hoặc Đỉnh 4 của Kim tự tháp, trao cho bạn nguồn năng lượng mạnh mẽ, linh hoạt để dìu dắt và truyền cảm hứng cho người khác.', 'GAP_GI', 1, 'Ch.11', 184, 185, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(195, 'PYT-PHI-DINH-10-DI', 'Hướng đi trong Đỉnh Kim tự tháp số 10 — Giai đoạn dẫn dắt & nâng đỡ tinh thần (Đỉnh 3–4)', 'QUY_TAC', 12, 1, '10', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "10"}', 'Ở Đỉnh số 10, bạn có trách nhiệm dùng kinh nghiệm từng trải để hỗ trợ cộng đồng với sự tự tin và tấm lòng rộng mở.', 'DI_THE_NAO', 1, 'Ch.11', 184, 185, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(196, 'PYT-PHI-DINH-11-GAP', 'Đỉnh Kim tự tháp số 11 — Giai đoạn khai mở trực giác & tâm linh bậc cao (Đỉnh 3–4)', 'QUY_TAC', 12, 1, '11', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "11"}', 'Theo Phillips và Quỳnh Hương, số 11 xuất hiện ở Đỉnh 3 hoặc Đỉnh 4 đòi hỏi sự trưởng thành chín muồi về tâm thức, lòng trắc ẩn và khả năng lan toả giá trị tinh thần sâu sắc.', 'GAP_GI', 1, 'Ch.11', 185, 186, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(197, 'PYT-PHI-DINH-11-DI', 'Hướng đi trong Đỉnh Kim tự tháp số 11 — Giai đoạn khai mở trực giác & tâm linh bậc cao (Đỉnh 3–4)', 'QUY_TAC', 12, 1, '11', '{"chi_so": "QH_DINH_HIEN_TAI", "bang": "11"}', 'Ở Đỉnh số 11, bạn nên dành thời gian cho thiền định, nghiên cứu triết lý nhân sinh và giữ đời sống thanh tịnh, cân bằng.', 'DI_THE_NAO', 1, 'Ch.11', 185, 186, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(198, 'PYT-PHI-DINH-8-CHU-DAO-CHAN', 'Đỉnh số 8 khi Con số chủ đạo là số chẵn: Xu hướng thành công tài chính - thương mại', 'QUY_TAC', 12, 1, '8:CHAN', '{"tat_ca": [{"chi_so": "QH_CHU_DAO", "chan": true}, {"chi_so": "QH_DINH_HIEN_TAI", "bang": "8"}]}', 'Theo David A. Phillips (Ch.11, tr.181), khi bạn đang ở Đỉnh số 8 và có Con số chủ đạo là số chẵn (2, 4, 6, 8, 10, 22/4), năng lượng của Đỉnh 8 có xu hướng thiên mạnh về phát triển tài chính, quản trị kinh doanh và xây dựng sự nghiệp vật chất vững chắc.', 'DI_THE_NAO', 1, 'Ch.11', 181, 182, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(199, 'PYT-PHI-DINH-8-CHU-DAO-LE', 'Đỉnh số 8 khi Con số chủ đạo là số lẻ: Xu hướng thành công nghệ thuật - nhân văn', 'QUY_TAC', 12, 1, '8:LE', '{"tat_ca": [{"chi_so": "QH_CHU_DAO", "chan": false}, {"chi_so": "QH_DINH_HIEN_TAI", "bang": "8"}]}', 'Theo David A. Phillips (Ch.11, tr.181), khi bạn đang ở Đỉnh số 8 và có Con số chủ đạo là số lẻ (3, 5, 7, 9, 11), năng lượng của Đỉnh 8 thường biểu hiện qua sự độc lập sáng tạo trong nghệ thuật, học thuật, triết học hoặc hoạt động nhân văn.', 'DI_THE_NAO', 1, 'Ch.11', 181, 182, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(200, 'PYT-PHI-GD-NIEN_THIEU', 'Giai đoạn 1: Niên thiếu (Từ đầu đời đến Đỉnh 1 Kim tự tháp)', 'QUY_TAC', 13, 1, 'NIEN_THIEU', '{"chi_so": "QH_GIAI_DOAN", "bang": "NIEN_THIEU"}', 'Theo Phillips và Quỳnh Hương, giai đoạn Niên thiếu (kéo dài từ lúc sinh cho đến tuổi đạt Đỉnh 1 = 36 trừ Con số chủ đạo) là thời kỳ học tập, hình thành nhân cách và chuẩn bị hành trang kiến thức cơ bản trước khi bước vào 27 năm trưởng thành.', 'GAP_GI', 1, 'Ch.10', 169, 172, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(201, 'PYT-PHI-GD-TRUONG_THANH', 'Giai đoạn 2: Trưởng thành (27 năm chinh phục 4 Đỉnh Kim tự tháp)', 'QUY_TAC', 13, 1, 'TRUONG_THANH', '{"chi_so": "QH_GIAI_DOAN", "bang": "TRUONG_THANH"}', 'Theo Phillips và Quỳnh Hương, giai đoạn Trưởng thành kéo dài đúng 27 năm (3 chu kỳ 9 năm từ Đỉnh 1 đến Đỉnh 4): đây là thời kỳ năng động nhất để xây dựng sự nghiệp, tự lập tài chính và hoàn thành các mục tiêu trọng tâm của cuộc đời.', 'GAP_GI', 1, 'Ch.10', 169, 172, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(202, 'PYT-PHI-GD-VIEN_MAN', 'Giai đoạn 3: Viên mãn (Từ Đỉnh 4 Kim tự tháp trở đi)', 'QUY_TAC', 13, 1, 'VIEN_MAN', '{"chi_so": "QH_GIAI_DOAN", "bang": "VIEN_MAN"}', 'Theo Phillips và Quỳnh Hương, từ năm đạt Đỉnh 4 trở đi bạn bước vào giai đoạn Viên mãn: trọng tâm chuyển từ độc lập tài chính sang độc lập tinh thần, đúc kết trí tuệ và truyền trao giá trị cho thế hệ sau.', 'GAP_GI', 1, 'Ch.10', 169, 172, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(203, 'PYT-PHI-SO-0-TAM-LINH', 'Biểu tượng số 0 trong Pythagoras (Phillips — Tiềm năng tâm linh vô hạn)', 'QUY_TAC', 24, 1, 'CO_SO_0', '{"chi_so": "CO_SO_0", "bang": true}', 'Theo David A. Phillips (Ch.3, tr.8) và Quỳnh Hương, số 0 không được điền vào lưới Biểu đồ ngày sinh nhưng là biểu tượng huyền học tối cao của sự vô cực, tiềm năng tâm linh bẩm sinh và khả năng thích ứng vượt giới hạn (đặc biệt thể hiện ở số 10).', 'AI', 1, 'Ch.3', 7, 8, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(204, 'PYT-PHI-LICH-SU-TEMPLETON', 'Nguồn gốc lịch sử Biểu đồ ngày sinh và Mũi tên cá tính (Hettie Templeton)', 'LICH_SU', 4, 1, NULL, NULL, 'Theo lời kể của David A. Phillips (Ch.1, tr.1; Ch.6, tr.51), mặc dù nền tảng triết học về số bắt nguồn từ Pythagoras cổ đại, hệ thống Biểu đồ ngày sinh 3×3 hiện đại và các Mũi tên cá tính thực chất do bà Hettie Templeton (thầy của Phillips tại Úc) hệ thống hoá và giảng dạy vào giữa thế kỷ 20.', 'NEN_TANG', 1, 'Ch.1', 1, 3, 'CAO', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(205, 'PYT-QH-QUY-TAC-CHU-Y', 'Quy tắc chữ Y luôn là nguyên âm trong tên tiếng Việt (Quỳnh Hương)', 'CONG_THUC', 6, 1, NULL, NULL, 'Theo Lê Đỗ Quỳnh Hương (Phần 12, tr.312), trong tiếng Việt chữ Y luôn mang âm nguyên âm (như trong Thuỳ, Mỹ, Lý, Huy, Quỳnh), vì vậy hệ thống quy định A, E, I, O, U, Y luôn là nguyên âm khi tính toán tên tiếng Việt.', 'NEN_TANG', 2, 'Phần 12', 311, 313, 'CAO', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(206, 'PYT-PHI-CH12-HANH-TINH', 'Liên hệ Số học và Chiêm tinh học theo David A. Phillips (Ch.12)', 'MO_TA', 26, 1, NULL, NULL, 'Trong Chương 12 (tr.186–228), Phillips liên hệ các con số với các cung Hoàng đạo và hành tinh phương Tây (khác với bảng hành tinh Vệ Đà của Johari và hai bảng Kabbalah của Sepharial).', 'NEN_TANG', 1, 'Ch.12', 186, 195, 'THAP', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL),
(207, 'PYT-PHI-CH15-ESP-KHONG-DUNG', 'Phát triển ngoại cảm (ESP) và thần giao cách cảm bằng Thần số học (Phillips Ch.15)', 'MO_TA', 29, 1, NULL, NULL, 'Nội dung bàn về khả năng ngoại cảm (Extra-Sensory Perception - ESP) và thần giao cách cảm trong Chương 15 của David A. Phillips.', 'NEN_TANG', 1, 'Ch.15', 262, 266, 'THAP', 'KHONG_DUNG', 'Theo quy tắc Mục 9.1: Nội dung về ngoại cảm (ESP) không có cơ sở kiểm chứng, gắn nhãn KHONG_DUNG và không hiển thị ở Khám phá.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(208, 'PYT-PHI-CH16-LUAN-HOI-KHONG-DUNG', 'Quan niệm về Luân hồi và Linh hồn già trong Thần số học (Phillips Ch.16)', 'MO_TA', 29, 1, NULL, NULL, 'Nội dung bàn về luân hồi, tiền kiếp và khái niệm ''linh hồn già'' (old souls) trong Chương 16 của David A. Phillips.', 'NEN_TANG', 1, 'Ch.16', 267, 270, 'THAP', 'KHONG_DUNG', 'Theo quy tắc Mục 9.1: Nội dung về ''linh hồn già'', luân hồi, kiếp trước gắn nhãn KHONG_DUNG để tránh phán xét tâm linh.', 1, 'DA_DUYET', 'system', 'admin', NULL),
(476, 'PYT-QH-GHI-CHU-TEN-THUONG-GOI', 'Ghi chú về Tên thường gọi so với Họ tên khai sinh', 'MO_TA', 8, 1, NULL, NULL, 'Theo cả David A. Phillips và Harish Johari, tên được gọi thường xuyên nhất trong giao tiếp hàng ngày mang trường năng lượng trực tiếp; tuy nhiên trong biểu mẫu tra cứu một trường tên, hệ thống sử dụng thống nhất họ và tên đầy đủ người dùng nhập (CẦN XÁC MINH thêm trang đối chiếu chi tiết).', 'NEN_TANG', 2, 'Phần 12', NULL, NULL, 'TRUNG_BINH', 'DUNG', NULL, 1, 'DA_DUYET', 'system', 'admin', NULL);
